class Solution {
    private int[] parent;
    private double[] weight; // node / parent

    public boolean checkContradictions(List<List<String>> equations, double[] values) {
        Map<String, Integer> id = new HashMap<>();
        for (List<String> e : equations)
            for (String s : e) id.putIfAbsent(s, id.size());
        int n = id.size();
        parent = new int[n];
        weight = new double[n];
        for (int i = 0; i < n; i++) { parent[i] = i; weight[i] = 1; }
        for (int i = 0; i < equations.size(); i++) {
            int a = id.get(equations.get(i).get(0)), b = id.get(equations.get(i).get(1));
            int ra = find(a), rb = find(b);
            double wa = weight[a], wb = weight[b], v = values[i];
            if (ra == rb) {
                if (Math.abs(wa / wb - v) >= 1e-5) return true;
            } else {
                parent[ra] = rb;
                weight[ra] = v * wb / wa;
            }
        }
        return false;
    }

    private int find(int x) {
        if (parent[x] == x) return x;
        int p = parent[x];
        int r = find(p);
        weight[x] *= weight[p];
        parent[x] = r;
        return r;
    }
}
